//! 🎟️ The defining fixture caller keeps one issued stock and its actual recipient through source root closure.
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation,OriginalTurnFailure};
use semio_framework_value::{RetainedCloneGrant as Grant,RetainedCloneProgress as Progress,ValueError,ValueRefusalKind};
#[global_allocator]
static ORIGINAL_CALLER_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
use std::cell::Cell;
thread_local!{static NOW:Cell<Option<u64>>=const{Cell::new(Some(1000))};}
fn clock()->Option<u64>{NOW.with(Cell::get)}
fn grant()->Grant{Grant{maximum_items:64,maximum_copy_bytes:9,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64}}
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}

#[test]
fn original_fixture_caller_keeps_one_stock_recipient_fuel_and_paid_root_close(){
 NOW.with(|now|now.set(Some(1000)));let law=fixture();let mut caller=OriginalJobFixtureCaller::admit(OperationId(941),Generation(17),grant(),clock,2000,13);let born=caller.born_bytes();let original=caller.cancel()as*const _;let source=caller.cumulative_receipt();assert_eq!(source.copied_items,3);assert_eq!(source.retained_capacity_bytes,born);assert_eq!(caller.fuel_remaining(),10);let mut recipient=None;let mut failed=None;
 for action in law["actions"].as_array().unwrap(){
  let count=action["copy"].as_u64().unwrap()as usize;let fuel=action["fuel"].as_u64().unwrap();let failure=action["failed"].as_bool().unwrap();let policy=Grant{maximum_items:1,maximum_copy_bytes:count,..grant()};let before=caller.cumulative_receipt();let original_fuel=caller.fuel_remaining();
  for denied in [Grant{maximum_items:0,..policy},Grant{maximum_depth:0,..policy}]{let(result,heap)=observe(||caller.turn(denied,|cx|{assert_eq!(cx.original_cancel_token()as*const _,original);assert_eq!(cx.operation(),OperationId(941));assert_eq!(cx.generation(),Generation(17));assert_eq!(cx.deadline_us(),2000);assert!(std::ptr::fn_addr_eq(cx.clock_source(),clock as fn()->Option<u64>));assert!(cx.retained_grant().maximum_items==0||cx.retained_grant().maximum_depth==0);Ok(())}));result.unwrap();assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Progress::default());assert_eq!(caller.cumulative_receipt(),before);assert_eq!(caller.fuel_remaining(),original_fuel)}
  let(result,heap)=observe(||caller.turn(policy,|cx|{let identity=cx.original_recipient_identity();if let Some(expected)=recipient{assert_eq!(identity,expected)}else{recipient=Some(identity)}assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),original_fuel);assert!(cx.retained_grant().maximum_items<=policy.maximum_items);assert!(cx.retained_grant().maximum_copy_bytes<=policy.maximum_copy_bytes);let mut output=[0u8;3];output[..count].copy_from_slice(&b"abc"[..count]);assert_eq!(&output[..count],&b"abc"[..count]);let receipt=Progress{copied_items:1,copied_bytes:count,..Default::default()};cx.consume_fuel(fuel);if failure{return Err(OriginalTurnFailure::debit_original(ValueError::literal(ValueRefusalKind::InvalidValue,"original failed action").with_retained_progress(receipt),cx))}cx.consume_retained(receipt)?;Ok(())}));assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Progress{copied_items:1,copied_bytes:count,..Default::default()});assert_eq!(caller.cumulative_receipt(),before.checked_add(caller.receipt()).unwrap());assert_eq!(caller.fuel_remaining(),original_fuel-fuel);if failure{failed=Some(result.unwrap_err())}else{result.unwrap()}
 }
 assert_eq!(caller.remaining_grant().maximum_copy_bytes,3);assert_eq!(caller.fuel_remaining(),5);assert_eq!(caller.stock(),grant());assert_eq!(caller.cumulative_receipt().copied_bytes,6);let before=caller.cumulative_receipt();let fuel=caller.fuel_remaining();let(result,heap)=observe(||caller.retire_step(Grant{maximum_items:0,..grant()}));assert_eq!(result.unwrap().progress(),Progress::default());assert_eq!(heap,(0,0));assert_eq!(caller.cumulative_receipt(),before);assert_eq!(caller.fuel_remaining(),fuel);
 semio_framework_async::poll::resolve_ready(caller.cancel().cancel());let mut released=0;let mut closed=0;for _ in 0..64{if caller.terminal_is_empty(){break}let before=caller.cumulative_receipt();let fuel=caller.fuel_remaining();let(step,heap)=observe(||caller.retire_step(grant()).unwrap());let receipt=step.progress();assert_eq!(receipt,caller.receipt());assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert_eq!(caller.cumulative_receipt(),before.checked_add(receipt).unwrap());assert_eq!(caller.fuel_remaining(),fuel-receipt.copied_items as u64);released+=heap.1;closed+=receipt.copied_items;}
 assert!(caller.terminal_is_empty());assert_eq!(released,born);assert_eq!(caller.cumulative_receipt().retained_capacity_bytes,caller.cumulative_receipt().released_bytes);assert_eq!(caller.fuel_remaining(),5-closed as u64);assert_eq!(observe(||drop(caller)).1,(0,0));assert_eq!(observe(||drop(failed)).1,(0,0));
}

#[test]
fn original_fixture_caller_restores_narrowed_loan_after_unwind_and_deadline(){
 NOW.with(|now|now.set(Some(1000)));let mut caller=OriginalJobFixtureCaller::admit(OperationId(941),Generation(17),grant(),clock,2000,13);let before=caller.cumulative_receipt();let mut recipient=0;
 let unwind=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let _=caller.turn::<()>(Grant{maximum_items:1,maximum_copy_bytes:1,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1},|cx|{recipient=cx.original_recipient_identity();cx.consume_retained(Progress{copied_items:1,copied_bytes:1,..Default::default()})?;cx.consume_fuel(2);panic!("original caller loan unwind")});}));assert!(unwind.is_err());assert_eq!(caller.fuel_remaining(),8);assert_eq!(caller.cumulative_receipt(),before.checked_add(Progress{copied_items:1,copied_bytes:1,..Default::default()}).unwrap());assert_eq!(caller.receipt(),Progress{copied_items:1,copied_bytes:1,..Default::default()});
 caller.turn(grant(),|cx|{assert_eq!(cx.original_recipient_identity(),recipient);assert_eq!(cx.fuel_remaining(),8);assert_eq!(cx.retained_grant().maximum_copy_bytes,8);assert_eq!(cx.retained_grant().maximum_depth,64);Ok(())}).unwrap();let before=caller.cumulative_receipt();NOW.with(|now|now.set(None));let(result,heap)=observe(||caller.turn(grant(),|cx|{assert!(cx.should_yield());assert_eq!(cx.deadline_us(),2000);assert_eq!(cx.latest_us(),Some(1000));Ok(())}));result.unwrap();assert_eq!(heap,(0,0));assert_eq!(caller.cumulative_receipt(),before);assert_eq!(caller.fuel_remaining(),8);let(step,heap)=observe(||caller.retire_step(grant()).unwrap());assert_eq!(step.progress(),Progress::default());assert_eq!(heap,(0,0));assert_eq!(caller.cumulative_receipt(),before);assert!(!caller.terminal_is_empty());NOW.with(|now|now.set(Some(1000)));let born=caller.born_bytes();assert_eq!(caller.retire(grant()),born);let mut stride=semio_framework_job::ClockStride::new();stride.begin(Some(1000));stride.begin(Some(2000));NOW.with(|now|now.set(Some(2000)));assert_eq!(stride.read(clock),Some(2000));NOW.with(|now|now.set(Some(1000)));let mut cached=0;while let Some(last)=stride.read(clock){assert_eq!(last,2000);cached+=1;assert!(cached<=semio_framework_job::ClockStride::MAXIMUM_STRIDE);}assert_eq!(stride.latest_us(),Some(2000));NOW.with(|now|now.set(Some(2000)));assert_eq!(stride.read(clock),Some(2000));
}

#[test]
fn original_fixture_caller_keeps_monotonic_clock_observation_across_turns_and_root_close(){
 NOW.with(|now|now.set(Some(1000)));let law=fixture();let mut caller=OriginalJobFixtureCaller::admit(OperationId(941),Generation(17),grant(),clock,2000,13);let mut recipient=0;
 caller.turn(grant(),|cx|{recipient=cx.original_recipient_identity();assert_eq!(cx.now_us(),Some(1000));assert_eq!(cx.latest_us(),Some(1000));Ok(())}).unwrap();let before=caller.cumulative_receipt();let fuel=caller.fuel_remaining();NOW.with(|now|now.set(Some(law["clockRegression"][1].as_u64().unwrap())));
 let(result,heap)=observe(||caller.turn(grant(),|cx|{assert_eq!(cx.original_recipient_identity(),recipient);assert!(cx.should_yield(),"original caller must reject backwards observed time rather than reset its stride");assert_eq!(cx.latest_us(),Some(1000));Ok(())}));result.unwrap();assert_eq!(heap,(0,0));assert_eq!(caller.cumulative_receipt(),before);assert_eq!(caller.fuel_remaining(),fuel);let(step,heap)=observe(||caller.retire_step(grant()).unwrap());assert_eq!(step.progress(),Progress::default());assert_eq!(heap,(0,0));assert_eq!(caller.cumulative_receipt(),before);assert_eq!(caller.fuel_remaining(),fuel);assert!(!caller.terminal_is_empty());NOW.with(|now|now.set(Some(law["clockRegression"][2].as_u64().unwrap())));caller.turn(grant(),|cx|{assert_eq!(cx.now_us(),Some(1000));assert_eq!(cx.original_recipient_identity(),recipient);Ok(())}).unwrap();let born=caller.born_bytes();assert_eq!(caller.retire(grant()),born);
}

#[test]
fn original_fixture_caller_work_loan_preserves_actual_fuel_deadline_clock_and_recipient(){
 NOW.with(|now|now.set(Some(1000)));let law=fixture();let mut caller=OriginalJobFixtureCaller::admit(OperationId(941),Generation(17),grant(),clock,2000,13);let born=caller.born_bytes();
 caller.turn(grant(),|cx|{
  let recipient=cx.original_recipient_identity();let cancel=cx.original_cancel_token()as*const _;let parent=cx.original_source_parent()? as*const _;let original_deadline=cx.deadline_us();
  for loan in law["workLoans"].as_array().unwrap(){let fuel=loan["fuel"].as_u64().unwrap();let deadline=loan["deadline"].as_u64().unwrap();let spend=loan["spent"].as_u64().unwrap();let before=cx.fuel_remaining();let receipt=cx.retained_progress();let execute=|same:&mut semio_framework_job::StepContext<'_>|{
   assert_eq!(same.fuel_remaining(),before.min(fuel));assert_eq!(same.deadline_us(),original_deadline.min(deadline));assert_eq!(same.original_recipient_identity(),recipient);assert_eq!(same.original_cancel_token()as*const _,cancel);assert_eq!(same.original_source_parent()? as*const _,parent);assert_eq!((same.operation(),same.generation()),(OperationId(941),Generation(17)));assert!(std::ptr::fn_addr_eq(same.clock_source(),clock as fn()->Option<u64>));assert_eq!(same.retained_progress(),receipt);
   if spend==0{assert!(same.should_yield());return Ok(())}assert!(!same.should_yield());same.consume_fuel(spend);same.consume_retained(Progress{copied_items:1,..Default::default()})?;if loan["unwind"].as_bool().unwrap(){std::panic::panic_any(())}Ok(())
  };
  if loan["unwind"].as_bool().unwrap(){let answer=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||cx.with_original_work_loan(fuel,deadline,execute)));assert!(answer.is_err());}
  else{let(answer,heap)=observe(||cx.with_original_work_loan(fuel,deadline,execute));answer?;assert_eq!(heap,(0,0));}
  assert_eq!(cx.fuel_remaining(),loan["remaining"].as_u64().unwrap());assert_eq!(cx.deadline_us(),original_deadline);assert_eq!(cx.original_recipient_identity(),recipient);assert_eq!(cx.retained_progress(),receipt.checked_add(Progress{copied_items:usize::from(spend!=0),..Default::default()})?);assert!(!cx.should_yield());
  }
  cx.with_retained_loan(Grant{maximum_items:0,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:0},|same|same.with_original_work_loan(99,3000,|child|{assert_eq!(child.retained_grant(),Grant::default());assert_eq!(child.fuel_remaining(),6);assert_eq!(child.deadline_us(),2000);Ok(())}))?;
  let before=cx.retained_progress();let before_fuel=cx.fuel_remaining();cx.with_original_work_loan(2,1100,|same|{NOW.with(|now|now.set(Some(1500)));while same.now_us()!=Some(1500){}assert!(same.should_yield());Ok(())})?;assert_eq!(cx.latest_us(),Some(1500));assert_eq!(cx.deadline_us(),2000);assert!(!cx.should_yield());assert_eq!(cx.fuel_remaining(),before_fuel);assert_eq!(cx.retained_progress(),before);NOW.with(|now|now.set(Some(1400)));for _ in 0..=semio_framework_job::ClockStride::MAXIMUM_STRIDE{let _=cx.now_us();}assert!(cx.should_yield());assert_eq!(cx.latest_us(),Some(1500));NOW.with(|now|now.set(Some(1500)));assert!(!cx.should_yield());Ok(())
 }).unwrap();assert_eq!(caller.fuel_remaining(),6);let(released,heap)=observe(||caller.retire(grant()));assert_eq!(released,born);assert_eq!(heap,(0,born));
}
